def find_missing(arr, n):
    left, right = 0, n - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] != mid + 1:
            return mid + 1
        elif arr[mid] == mid + 1 and mid < n - 1 and arr[mid + 1] == mid + 2:
            left = mid + 2
        else:
            right = mid - 1

    return n
