def find_Nth_Digit(numerator, denominator, position):
    # Calculate the length of the repeating sequence
    length = len(str(denominator))

    # Find the quotient and remainder when numerator is divided by denominator
    quotient, remainder = divmod(numerator, denominator)

    # If remainder is zero, return the last digit of the quotient
    if remainder == 0:
        return int(str(quotient)[-1])

    # Calculate the number of digits in the quotient part
    quotient_digits = len(str(quotient))

    # Calculate the total number of digits contributed by the quotient and remainder
    total_digits = quotient_digits + remainder * length

    # If position is less than or equal to the total number of digits in the quotient part
    if position <= quotient_digits:
        # Return the corresponding digit from the quotient
        return int(str(quotient)[position - 1])
    else:
        # Calculate the position within the repeating sequence
        position -= quotient_digits

        # Return the corresponding digit from the repeating sequence
        return int(str(denominator)[position - 1])
```

