def find_Sum(arr,n):
    # Initialize a dictionary to store the frequency of each element
    freq = {}

    # Iterate through the array and update the frequency of each element
    for i in range(n):
        if arr[i] in freq:
            freq[arr[i]] += 1
        else:
            freq[arr[i]] = 1

    # Calculate the sum of repeated elements
    sum_repeated = sum(freq[key] * key for key in freq)

    return sum_repeated
