def search(arr, n):
    low = 0
    high = n - 1

    while low <= high:
        mid = (low + high) // 2

        # If mid is even and arr[mid] is equal to arr[mid+1]
        if mid % 2 == 0 and arr[mid] == arr[mid + 1]:
            low = mid + 2
        # If mid is odd and arr[mid] is equal to arr[mid-1]
        elif mid % 2 != 0 and arr[mid] == arr[mid - 1]:
            high = mid - 2
        else:
            return arr[mid]

    return -1
```

