```python
def magic_square_test(square):
    n = len(square)
    if n != 4 or any(len(row) != n for row in square):
        return False

    # Calculate the sum of the first row
    target_sum = sum(square[0])

    # Check rows and columns
    for i in range(n):
        if sum(square[i]) != target_sum or sum(square[j][i] for j in range(n)) != target_sum:
            return False

    # Check diagonals
    if sum(square[i][i] for i in range(n)) != target_sum or sum(square[i][n-i-1] for i in range(n)) != target_sum:
        return False

    return True
```

