def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Fill the table
    for i in range(1, n):
        for j in range(1, n):
            if s[i-1] == s[j-1] and i != j:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n-1][n-1]
```

