def sort_on_occurrence(lst):
    # Count occurrences of each tuple's first element
    counts = {}
    for tup in lst:
        if tup[0] not in counts:
            counts[tup[0]] = [tup]
        else:
            counts[tup[0]].append(tup)

    # Sort by count and then by tuple itself
    sorted_lst = sorted(counts.items(), key=lambda x: (-len(x[1]), x[0]))

    # Flatten the list of lists into a single list
    result = []
    for tup_list in sorted_lst:
        result.extend(tup_list)

    return result
```

