from math import gcd

def modular_inverse(arr, n, p):
    result = [0] * len(arr)
    for i in range(len(arr)):
        if gcd(arr[i], p) != 1:
            raise ValueError("Modular inverse does not exist for this element")
        result[i] = pow(arr[i], -1, p)
    return result
```

