def max_sum_increasing_subseq(nums, n, k, m):
    dp = [[0] * (m+1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, m+1):
            if nums[i-1] < nums[k]:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] + nums[i])
            else:
                dp[i][j] = dp[i-1][j]

    return dp[n-1][m]
```

