def permute_string(s):
    if len(s) == 1:
        return [s]
    perms = []
    for i in range(len(s)):
        char = s[i]
        remaining_chars = s[:i] + s[i+1:]
        for perm in permute_string(remaining_chars):
            perms.append(char + perm)
    return perms
```

