def get_maxgold(mine, rows, cols):
    dp = [[0]*cols for _ in range(rows)]

    # Fill the first row of dp table
    for j in range(cols):
        dp[0][j] = mine[0][j]

    # Fill the first column of dp table
    for i in range(1, rows):
        dp[i][0] = mine[i][0] + max(dp[i-1][0], dp[i-1][1])

    # Fill the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = mine[i][j] + max(dp[i-1][j], dp[i-1][j-1], dp[i-1][j+1])

    # Find the maximum value in the last row of dp table
    return max(dp[-1])
```

