def max_product(nums, n):
    # Initialize the dp array where dp[i] will store the maximum product ending at index i
    dp = [1] * n

    # Iterate through each element in the array
    for i in range(1, n):
        # For each element, check all previous elements to find the maximum product ending at i
        for j in range(i):
            if nums[j] < nums[i]:
                # Update dp[i] if the current element can form a larger product
                dp[i] = max(dp[i], dp[j] * nums[i])

    # The maximum product is the maximum value in the dp array
    return max(dp)
```

