def is_subset_sum(nums, target, current_sum=0):
    # Base case: if current_sum equals target, return True
    if current_sum == target:
        return True
    # If current_sum exceeds target or all elements have been considered, return False
    if current_sum > target or len(nums) == 0:
        return False
    # Recursive case: include the current element in the sum and exclude it
    return is_subset_sum(nums[1:], target, current_sum + nums[0]) or is_subset_sum(nums[1:], target, current_sum)
```

