def no_of_subsequences(arr, k):
    n = len(arr)
    count = 0
    for i in range(n):
        product = arr[i]
        if product < k:
            count += 1
        for j in range(i+1, n):
            product *= arr[j]
            if product < k:
                count += 1
    return count
```

